export type IconCategory = keyof typeof ICON_CATEGORIES;
export const GENERIC_ICONS = Object.values(ICON_CATEGORIES).flat();
export type GenericIconId = (typeof GENERIC_ICONS)[number];

// Format tersimpan di links.icon: "brand:whatsapp", "generic:Mail", atau "emoji:🔥"
// (emoji bebas, gak ada daftar terbatas kayak brand/generic). null = auto (favicon).
export function parseIconValue(
  value: string | null,
): { kind: "brand" | "generic" | "emoji"; id: string } | null {
  if (!value) return null;
  const sep = value.indexOf(":");
  if (sep === -1) return null;
  const kind = value.slice(0, sep);
  const id = value.slice(sep + 1);
  if (kind === "brand" && id in BRAND_ICONS) return { kind: "brand", id };
  if (kind === "generic" && (GENERIC_ICONS as readonly string[]).includes(id)) return { kind: "generic", id };
  if (kind === "emoji" && id.trim().length > 0) return { kind: "emoji", id };
  return null;
}
